<script setup lang="ts">
const email=ref('');const busy=ref(false);const error=ref('');const sent=ref(false);useHead({title:'Forgot Password'})
async function submit(){busy.value=true;error.value='';try{const csrf=(await $fetch<{csrfToken:string}>('/api/auth/csrf')).csrfToken;await $fetch('/api/auth/forgot-password',{method:'POST',body:{email:email.value,csrfToken:csrf}});await navigateTo('/password-reset-sent')}catch(e:any){error.value=e?.data?.statusMessage||e?.message||'Could not request a password reset.'}finally{busy.value=false}}
</script>
<template><section class="auth-page"><div class="auth-card"><div class="auth-icon">🔑</div><h1>Forgot Password?</h1><p class="auth-subtitle">Enter your email and we'll send you a reset link.</p><p v-if="error" class="flash error">{{error}}</p><div v-if="sent" class="flash success">If an account matches that email, a reset link has been sent.</div><form v-else @submit.prevent="submit"><div class="form-group"><label for="email">Email</label><input id="email" v-model="email" type="email" autocomplete="email" required></div><button type="submit" class="button button-gold button-full" :disabled="busy">{{busy?'Sending…':'Send Reset Link'}}</button></form><p class="auth-footer"><NuxtLink to="/login">Back to Login</NuxtLink></p></div></section></template>
